"""End to end: an events file generated by capture_waterfall.write_outputs()
from a settings log with a single gain, bandwidth or gain-mode change,
replayed through the native daemon (app/classifier/build/host/
classifier_replay), must make the daemon relearn its background at the
change (learn_count 2, config generation 1), exactly as the MQTT message
would on the sensor. This is the reproduction of the 1791089 readiness
review (C1): with only frequency and span seeded at t = 0 the daemon took
the first gain value as initialisation and the capture-generated change
was ignored (one learn, generation 0).

Needs the host tools: make -C app/classifier host-tools. Skipped otherwise.
"""
import argparse
import json
import subprocess
import sys
from pathlib import Path

import pytest

HERE = Path(__file__).resolve().parent
REPO = HERE.parents[3]
APP = REPO / "app" / "classifier"
REPLAY = APP / "build" / "host" / "classifier_replay"
FRAMES_DIR = APP / "tests" / "fixtures"
STOCK_BUNDLE = REPO / "board" / "tezuka" / "common" / "overlay_tezuka" / "etc" / "classifier-default-templates.bin"
sys.path.insert(0, str(HERE.parent))
import capture_waterfall as cw  # noqa: E402

N = 4096
FPS = 7.5
LEARN_S = 10
SECONDS = 40
CHANGE_AFTER_FRAMES = 150            # 20 s: well after the first learn, well before the end

API0 = {"ad9361": {"sampling_frequency": 2500000, "rx_rf_bandwidth": 2500000, "rx_lo_frequency": 1090000000,
                   "rx_gain": 70.0, "rx_gain_mode": "Manual"},
        "spectrometer": {"output_sampling_frequency": FPS, "fft_size": N, "number_integrations": 1023, "mode": "Average",
                         "input": "AD9361", "input_sampling_frequency": 2500000.0}}

pytestmark = pytest.mark.skipif(not REPLAY.exists(), reason="native classifier_replay not built (make -C app/classifier host-tools)")


def make_raw(path):
    frames = [(FRAMES_DIR / f"wf_avg4096_frame{i}.bin").read_bytes() for i in range(3)]
    assert all(len(f) == N * 4 for f in frames)
    n = int(round(SECONDS * FPS))
    with open(path, "wb") as f:
        for i in range(n):
            f.write(frames[i % 3])
    return n


def generated_events(tmp_path, key, new):
    """What capture_waterfall writes for a capture whose only logged change
    is KEY -> NEW after CHANGE_AFTER_FRAMES frames."""
    out = tmp_path / "cap.raw"
    make_raw(out)
    api_after = json.loads(json.dumps(API0))
    api_after["ad9361"][key] = new
    meta = {"api": API0, "fps_api_start": FPS, "started_unix_s": 0.0, "frame_sizes": {str(N * 4): 300}, "frames": 300,
            "poll_errors": [], "aborted": None, "interrupted": False, "finalised": True,
            "settings_log": [{"t_unix_s": 20.0, "t_rel_s": 20.0, "frames_received": CHANGE_AFTER_FRAMES,
                              "t_replay_s": CHANGE_AFTER_FRAMES / FPS, "t_event_s": cw.event_time(CHANGE_AFTER_FRAMES, FPS),
                              "changed": {key: [API0["ad9361"][key], new]},
                              "ad9361": api_after["ad9361"], "spectrometer": api_after["spectrometer"]}]}
    args = argparse.Namespace(out=str(out), host="fake", poll=1.0)
    cw.write_outputs(args, meta, API0)
    return out, Path(str(out) + ".events")


def replay(raw, events):
    p = subprocess.run([str(REPLAY), "-r", str(raw), "-n", str(N), "-F", str(FPS), "-B", "none", "-S", "2500000",
                        "-l", str(LEARN_S), "-i", "1.0", "-f", str(STOCK_BUNDLE), "-E", str(events)],
                       capture_output=True, text=True, timeout=300)
    assert p.returncode == 0, p.stderr
    obs = []
    for line in p.stdout.splitlines():
        parts = line.split(" ", 2)
        if len(parts) == 3 and parts[1].endswith("/observation"):
            obs.append((float(parts[0]), json.loads(parts[2])))
    assert obs
    return obs


@pytest.mark.parametrize("key,new", [("rx_gain", 60.0), ("rx_rf_bandwidth", 1500000), ("rx_gain_mode", "SlowAttack")])
def test_generated_single_setting_change_relearns_the_background(tmp_path, key, new):
    raw, events = generated_events(tmp_path, key, new)
    body = [ln for ln in events.read_text().splitlines() if ln.strip() and not ln.startswith("#")]
    assert body[:6] == ["0 state/rx/frequency 1090000000", "0 state/rx/sampling 2500000", "0 state/rx/span 2500000",
                        "0 state/rx/bandwidth 2500000", "0 state/rx/gain 70", "0 state/rx/gain_mode Manual"]
    assert len(body) == 7 and body[6].split()[1] == cw.EVENT_TOPIC[key]

    obs = replay(raw, events)
    t_change = cw.event_time(CHANGE_AFTER_FRAMES, FPS)
    before = [o for t, o in obs if t < t_change]
    after = [o for t, o in obs if t >= t_change]
    assert before[-1]["background"]["learned"] is True
    assert before[-1]["config"]["generation"] == 0 and before[-1]["background"]["learn_count"] == 1
    assert after[0]["config"]["generation"] == 1             # the change was recognised as a change
    assert after[0]["background"]["learned"] is False        # and the background is being relearned
    assert obs[-1][1]["background"]["learn_count"] == 2
    assert obs[-1][1]["config"]["generation"] == 1


def test_unseeded_setting_change_is_ignored_by_the_daemon(tmp_path):
    """The defect the seeding fixes, kept as the negative control: the same
    gain change without the t = 0 gain line is taken as initialisation by
    the daemon (one learn, generation 0), so the test above discriminates."""
    raw, events = generated_events(tmp_path, "rx_gain", 60.0)
    lines = [ln for ln in events.read_text().splitlines() if not ln.startswith("0 state/rx/gain ")]
    events.write_text("\n".join(lines) + "\n")
    obs = replay(raw, events)
    assert obs[-1][1]["background"]["learn_count"] == 1
    assert all(o["config"]["generation"] == 0 for _, o in obs)
